/* @autogenerated */
package net.civeira.phylax.features.notification.outbox.infrastructure.smtp;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.argThat;
import static org.mockito.Mockito.verify;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import net.civeira.phylax.common.infrastructure.mail.EmailService;
import net.civeira.phylax.common.infrastructure.mail.MailConfiguration;
import net.civeira.phylax.features.notification.outbox.domain.model.OutboundMail;

/**
 * Unit tests for {@link SmtpMailSenderAdapter}.
 */
class SmtpMailSenderAdapterTest {

  @Mock
  private EmailService emailService;

  @InjectMocks
  private SmtpMailSenderAdapter adapter;

  @BeforeEach
  void setUp() {
    MockitoAnnotations.openMocks(this);
  }

  @Test
  @DisplayName("send(mail) delegates to emailService.sendMessage with correct fields")
  void send_withoutConfig_delegatesToEmailService() {
    OutboundMail mail = OutboundMail.builder().recipient("user@example.com").subject("Hello")
        .htmlContent("<p>World</p>").textContent("World").build();

    adapter.send(mail);

    verify(emailService).sendMessage(argThat(
        msg -> "user@example.com".equals(msg.getTargetAddress()) && "Hello".equals(msg.getSubject())
            && "<p>World</p>".equals(msg.getHtmlContent()) && "World".equals(msg.getContent())));
  }

  @Test
  @DisplayName("send(config, mail) delegates to emailService.sendMessage with config")
  void send_withConfig_delegatesToEmailServiceWithConfig() {
    MailConfiguration config =
        MailConfiguration.builder().smtpHost("smtp.example.com").smtpPort(465).build();
    OutboundMail mail = OutboundMail.builder().recipient("user@example.com").subject("Subject")
        .htmlContent("<p>Body</p>").textContent("Body").build();

    adapter.send(config, mail);

    verify(emailService).sendMessage(any(MailConfiguration.class),
        argThat(msg -> "user@example.com".equals(msg.getTargetAddress())));
  }

  @Test
  @DisplayName("send uses empty string for subject when mail has no subject")
  void send_usesEmptySubjectWhenNull() {
    OutboundMail mail =
        OutboundMail.builder().recipient("user@example.com").htmlContent("<p>Body</p>").build();

    adapter.send(mail);

    verify(emailService).sendMessage(argThat(msg -> "".equals(msg.getSubject())));
  }

  @Test
  @DisplayName("send uses htmlContent as content fallback when textContent is null")
  void send_usesHtmlAsContentFallbackWhenTextIsNull() {
    OutboundMail mail = OutboundMail.builder().recipient("user@example.com").subject("Hi")
        .htmlContent("<p>Hi</p>").build();

    adapter.send(mail);

    verify(emailService).sendMessage(argThat(msg -> "<p>Hi</p>".equals(msg.getContent())));
  }
}
